import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText renders a draft invoice with one line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = renderInvoiceText(invoice);
  assert.equal(r.ok, true);
  const text = r.value;
