import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, status: string, lines: Array, dueDate?: string, payments?: Array, voucher?: object }} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  // Get customer
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  // Calculate totals
  const totalsResult = invoiceTotals(invoice);
  if (!totalsResult.ok) return totalsResult;

  const lines = [];

  // Header: invoice number or DRAFT
  const header = invoice.number ?? 'DRAFT';
  lines.push(header);

  // Customer name
  lines.push(customerResult.value.name);

  // Invoice lines with discount info
  for (const line of invoice.lines) {
    const total = line.qty * line.unitPrice;
    const unitPriceStr = formatEuros(line.unitPrice);
    const lineTotalStr = formatEuros(total);
    let lineStr = `${line.qty}x ${line.name} @ ${unitPriceStr} = ${lineTotalStr}`;

    if (line.discountPercent > 0) {
      const discountAmount = Math.round(total * line.discountPercent / 100);
      const discountStr = formatEuros(discountAmount);
      lineStr += ` (-${line.discountPercent}% = ${discountStr})`;
    }

    lines.push(lineStr);
  }

  // Discount summary if any
  if (totalsResult.value.discount > 0) {
    const discountStr = formatEuros(totalsResult.value.discount);
    lines.push(`Discount: ${discountStr}`);
  }

  // VAT
  if (totalsResult.value.vat > 0) {
    const vatStr = formatEuros(totalsResult.value.vat);
    lines.push(`VAT: ${vatStr}`);
  }

  // Voucher
  if (totalsResult.value.voucher > 0) {
    const voucherStr = formatEuros(totalsResult.value.voucher);
    lines.push(`Voucher: ${voucherStr}`);
  }

  // Total
  const totalStr = formatEuros(totalsResult.value.total);
  lines.push(`Total: ${totalStr}`);

  // Due date
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount
  if (Array.isArray(invoice.payments) && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    const paidStr = formatEuros(paid);
    lines.push(`Paid: ${paidStr}`);
  }

  return ok(lines.join('\n'));
}

