import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText renders a draft invoice with one line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = renderInvoiceText(invoice);
  assert.equal(r.ok, true);
  const text = r.value;
  assert.match(text, /^DRAFT\n/);
  assert.match(text, /Kite & Co\n/);
  assert.match(text, /2x Design work \(hour\) @ €85\.00 = €170\.00\n/);
  assert.match(text, /VAT: €34\.81\n/);
  assert.match(text, /Total: €200\.56$/);
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const created = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const invoice = issueInvoice(created, []).value;

  const r = renderInvoiceText(invoice);
  assert.equal(r.ok, true);
  const text = r.value;
  assert.match(text, /^INV-2026-0001\n/);
});

test('renderInvoiceText with multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const r = renderInvoiceText(invoice);
  assert.equal(r.ok, true);
  const text = r.value;
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Kite & Co');
  assert.equal(lines[2], '2x Design work (hour) @ €85.00 = €170.00');
  assert.equal(lines[3], '3x Development (hour) @ €95.00 = €285.00');
  assert.equal(lines[4], 'VAT: €93.16');
  assert.equal(lines[5], 'Total: €536.79');
});

test('renderInvoiceText formats amounts with formatEuros', () => {
